import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import {pathToFileURL}from'node:url';
const root=process.argv[2],out=process.argv[3];const mod=async p=>import(pathToFileURL(path.join(root,p)));
const WB=await mod('bindings/continuity/workbench.js');const{StudioEngine}=await mod('bindings/continuity/studio.js');const{WorldEngine}=await mod('bindings/continuity/world.js');
const bytes=fs.readFileSync(path.join(root,'dist/nocturne.wasm')),schema=JSON.parse(fs.readFileSync(path.join(root,'studio.schema.json')));const engine=await StudioEngine.create(bytes,schema),world=await WorldEngine.create(bytes),renderer=new WB.WorkbenchRenderer(engine,world);
const rows=[];function make(scene){const m=new WB.WorkbenchModel();m.setScene(scene);m.resize(160,52);m.configure({motion:true});m.simulation=false;m.navEnabled=false;while(m.layoutJob)m.stepLayout(128);m.setTime(4000);return m;}
function point(v,predicate){for(let i=0;i<v.frame.cells.length;i+=4){const id=v.frame.cells[i+3],p={x:(i/4)%v.frame.width+.25,y:Math.floor(i/4/v.frame.width)+.25,id,action:v.actions[id]};if(predicate(p))return p;}throw Error('No actual visible source target');}
function snap(m,v){return {camera:m.camera.snapshot(),flightMode:m.flight.mode,travelHeading:m.flight.travelHeading(),selection:m.graphSelection,windows:m.spaceWindows.list(),frame:{width:v.frame.width,height:v.frame.height,words:Array.from(v.frame.cells)}};}
{const m=make('dag'),v=renderer.render(m),p=point(v,p=>p.action?.kind==='rich-node'),before=snap(m,v),intent=WB.beginWorkbenchPointer(m,v,p.x,p.y,{button:2});WB.moveWorkbenchPointer(m,intent,3,2);rows.push({id:'right-node-pan',point:p,intent,before,after:snap(m,renderer.render(m))});}
for(const delta of [[2,1],[100,-100],[-100,100]]){const m=make('windows'),v=renderer.render(m),p=point(v,p=>p.action?.kind==='select-window'),selected=m.spaceWindows.list().find(w=>w.id===p.action.value);m.spaceWindows.move(selected.id,{yaw:3,pitch:4});const view=renderer.render(m),q=point(view,p=>p.action?.kind==='select-window'&&p.action.value===selected.id),before=snap(m,view),intent=WB.beginWorkbenchPointer(m,view,q.x,q.y,{button:0,altKey:true});WB.moveWorkbenchPointer(m,intent,...delta);rows.push({id:'alt-window-'+delta.join('_'),point:q,intent,delta,before,after:snap(m,renderer.render(m))});}
{const m=make('warp');m.flight.cruise(m.motionMs,m.camera.snapshot(),10,{yaw:15,pitch:5});m.setTime(5000);const v=renderer.render(m),before=snap(m,v);m.wheel({deltaY:100});const after=snap(m,renderer.render(m));m.setTime(6000);rows.push({id:'wheel-cruise',sample:{deltaY:100},before,after,later:snap(m,renderer.render(m))});}
const sourceFiles=[];const seen=new Set();function closure(p){p=path.resolve(p);if(seen.has(p))return;seen.add(p);const b=fs.readFileSync(p);sourceFiles.push({path:p,sha256:crypto.createHash('sha256').update(b).digest('hex'),bytes:b.length});if(p.endsWith('.js'))for(const m of b.toString().matchAll(/(?:from\s*|import\s*)['"](\.[^'"]+)['"]/g))closure(path.resolve(path.dirname(p),m[1]));}
for(const p of ['bindings/continuity/workbench.js','bindings/continuity/studio.js','bindings/continuity/world.js','dist/nocturne.wasm','studio.schema.json'])closure(path.join(root,p));
fs.writeFileSync(out,JSON.stringify({schema:'nocturne.original-workbench-gesture-oracle.v1',sourceFiles,scope:'Actual retained source Workbench model and renderer with original native/WASM engine; native integration comparison is separate. Full original frames retained for custody, no pixel masking.',rows}));console.log(JSON.stringify({rows:rows.length,sourceFiles:sourceFiles.length,summary:rows.map(r=>({id:r.id,intent:r.intent?.kind,flight:r.after.flightMode,selection:[r.before.selection,r.after.selection],window:r.intent?.windowId? [r.before.windows.find(w=>w.id===r.intent.windowId),r.after.windows.find(w=>w.id===r.intent.windowId)]:undefined}))}));
